import os

zdjecia = []
for plik in sorted(os.listdir(".")):
    if plik.endswith(".jpg"):
        zdjecia.append(plik)
for numer, stara in enumerate(zdjecia, start=1):
    nowa = f"wycieczka_{numer:02d}.jpg"
    os.rename(stara, nowa)
    print(f"{stara} -> {nowa}")
